  body { margin: 0; background: var(--bg-subtle); color: var(--text-primary); font-family: Pretendard, "Apple SD Gothic Neo", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; letter-spacing: -.015em; }
  .nol-demo { min-height: 100vh; background: var(--bg-subtle); }
  .nol-demo .topnav { position: relative; overflow: hidden; }
