  .nol-demo .nav-links { margin-left: auto; display: flex; gap: var(--space-xl); position: relative; z-index: 1; }
  .nol-demo .hero { background: var(--gradient-brand); color: #FFFFFF; padding: 20px 24px 52px; position: relative; overflow: hidden; }
  .nol-demo .hero-inner { max-width: 1120px; margin: 0 auto; display: grid; grid-template-columns: minmax(0,1.1fr) minmax(300px,.9fr); align-items: center; gap: 44px; }
  .nol-demo .eyebrow { display: inline-flex; align-items: center; gap: 7px; padding: 6px 10px; background: rgba(255,255,255,.14); border: 1px solid rgba(255,255,255,.22); border-radius: var(--radius-full); font-size: 12px; font-weight: 800; }
  .nol-demo .hero h1 { margin: 16px 0 10px; max-width: 620px; font-size: clamp(34px,5vw,58px); font-weight: 900; line-height: 1.08; letter-spacing: -.055em; }
  .nol-demo .hero p { margin: 0; max-width: 540px; color: rgba(255,255,255,.82); font-size: 16px; font-weight: 600; line-height: 1.6; }
  .nol-demo .search-panel { margin-top: 24px; padding: 7px 7px 7px 18px; max-width: 540px; background: #FFFFFF; border-radius: var(--radius-full); display: flex; align-items: center; gap: 10px; box-shadow: var(--shadow-lg); }
  .nol-demo .search-panel svg { color: var(--color-primary-500); flex: 0 0 auto; }
  .nol-demo .search-panel span { color: var(--text-secondary); font-size: 14px; font-weight: 650; }
  .nol-demo .search-panel .btn { margin-left: auto; min-height: 40px; padding: 0 16px; }
  .nol-demo .travel-card { min-height: 310px; position: relative; overflow: hidden; border-radius: var(--radius-xl); background: linear-gradient(160deg,#B9E5F2 0%,#E7F5F4 49%,#F7C896 50%,#C87953 100%); box-shadow: 0 28px 60px rgba(47,14,72,.28); transform: rotate(2deg); }
  .nol-demo .travel-card::before { content: ""; position: absolute; width: 210px; height: 210px; right: -45px; top: -58px; background: #FFF3C4; border-radius: 50%; opacity: .9; }
  .nol-demo .travel-card::after { content: ""; position: absolute; left: -10%; right: -10%; bottom: 0; height: 42%; background: linear-gradient(160deg,#3D9A8C,#126E72); clip-path: polygon(0 48%,20% 24%,38% 52%,58% 8%,78% 46%,100% 20%,100% 100%,0 100%); }
  .nol-demo .trip-note { position: absolute; z-index: 2; right: 18px; bottom: 18px; width: 190px; padding: 16px; background: rgba(255,255,255,.94); color: var(--text-primary); border-radius: var(--radius-lg); box-shadow: var(--shadow-md); transform: rotate(-3deg); }
  .nol-demo .trip-note .tag { margin-bottom: 8px; }
  .nol-demo .trip-note strong { display: block; font-size: 18px; line-height: 1.25; letter-spacing: -.03em; }
  .nol-demo .trip-note small { display: block; margin-top: 6px; color: var(--text-tertiary); font-weight: 650; }
  .nol-demo .content { max-width: 1120px; margin: -28px auto 0; padding: 0 24px 48px; position: relative; z-index: 3; }
  .nol-demo .quick-strip { background: var(--bg-elevated); border: 1px solid var(--border-default); border-radius: var(--radius-xl); padding: 18px 20px; box-shadow: var(--shadow-md); display: grid; grid-template-columns: repeat(5,1fr); gap: 12px; }
  .nol-demo .quick-item { text-align: center; font-size: 12px; font-weight: 800; }
  .nol-demo .quick-icon { width: 48px; height: 48px; margin: 0 auto 8px; border-radius: 16px; display: grid; place-items: center; background: var(--color-primary-50); color: var(--color-primary-500); }
  .nol-demo .quick-item:nth-child(2) .quick-icon, .nol-demo .quick-item:nth-child(5) .quick-icon { background: var(--color-secondary-50); color: var(--color-secondary-500); }
  .nol-demo .quick-item:nth-child(3) .quick-icon { background: var(--color-info-bg); color: var(--color-info-fg); }
  .nol-demo .quick-item:nth-child(4) .quick-icon { background: var(--color-warning-bg); color: var(--color-warning-fg); }
  .nol-demo .section-head { margin: 34px 0 14px; display: flex; align-items:end; gap: 12px; }
  .nol-demo .section-head h2 { margin: 0; font-size: 24px; font-weight: 850; letter-spacing: -.035em; }
  .nol-demo .section-head p { margin: 0 0 2px; color: var(--text-tertiary); font-size: 13px; }
  .nol-demo .features { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; }
  .nol-demo .feature-card { min-height: 190px; position: relative; overflow: hidden; padding: 20px; background: var(--bg-elevated); border: 1px solid var(--border-default); border-radius: var(--radius-lg); }
  .nol-demo .feature-card .visual { height: 72px; margin: -20px -20px 16px; position: relative; overflow: hidden; }
  .nol-demo .feature-card:nth-child(1) .visual { background: linear-gradient(125deg,#FF6D9E,#FFB1C9); }
  .nol-demo .feature-card:nth-child(2) .visual { background: linear-gradient(125deg,#6B46C1,#A890E9); }
  .nol-demo .feature-card:nth-child(3) .visual { background: linear-gradient(125deg,#168BD2,#8ED8EE); }
  .nol-demo .feature-card .visual::after { content: ""; position: absolute; width: 92px; height: 92px; right: 18px; top: 18px; border-radius: 26px; background: rgba(255,255,255,.28); transform: rotate(24deg); }
  .nol-demo .feature-card h3 { margin: 0; font-size: 17px; font-weight: 850; letter-spacing: -.025em; }
  .nol-demo .feature-card p { margin: 7px 0 14px; color: var(--text-secondary); font-size: 13px; line-height: 1.5; }
  .nol-demo .price { display: flex; align-items: baseline; gap: 6px; font-size: 16px; font-weight: 900; }
  .nol-demo .price .discount { color: var(--color-primary-500); }
  .nol-demo .price small { color: var(--text-tertiary); font-size: 11px; font-weight: 600; }
  @media (max-width: 760px) {
    .nol-demo .nav-links { display: none; }
    .nol-demo .hero { padding: 16px 18px 46px; }
    .nol-demo .hero-inner { grid-template-columns: 1fr; }
    .nol-demo .travel-card { min-height: 220px; transform: none; }
    .nol-demo .quick-strip { grid-template-columns: repeat(5,1fr); padding: 14px 8px; gap: 4px; }
    .nol-demo .quick-icon { width: 40px; height: 40px; border-radius: 13px; }
    .nol-demo .quick-item { font-size: 10px; }
    .nol-demo .features { grid-template-columns: 1fr; }
  }
</style>

